import{_ as a,o as t,c as r,a5 as n}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"ランキングと競技を理解する","description":"","frontmatter":{"title":"ランキングと競技を理解する","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"b66c4ce6f03e8711db80b9d853304814c9afa05d3da7a929e7b1dce3fe1b058d","order":30},"headers":[],"relativePath":"ja/user/points/rankings.md","filePath":"ja/user/points/rankings.md","lastUpdated":1794611623000}'),i={name:"ja/user/points/rankings.md"};function o(s,e,d,l,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="understand-rankings-and-competitions" tabindex="-1">ランキングと競技を理解する <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;ランキングと競技を理解する {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>適切な順位表示を選び、開発中のランキング画面の制限を理解します。意味のあるスコアにはイベントの受信が必要です。現在の視聴者を確認するだけなら、通常の <a href="./rules.html">ポイント</a> の順位表や <a href="./../live/feed.html">ライブフィード</a> の上位視聴者パネルから始めます。</p><h2 id="use-the-right-view" tabindex="-1">適切な表示を使う <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;適切な表示を使う {#use-the-right-view}&quot;">​</a></h2><ol><li><strong>ポイント</strong> で視聴者を検索し、ポイント、レベル、視聴者 ID で並べ替えます。手動調整と付与を比べる前に更新します。</li><li><strong>ライブフィード</strong> の順位パネルを確認します。ポイント残高表とは独立してランキングエンジンのスナップショットを受け取る場合があります。</li><li>オーバーレイでは <a href="./../overlays/">オーバーレイ</a> のランキング種別を選び、ソースの設定を確認します。出力には設定済みランキングソースが必要です。</li></ol><p>専用の <strong>ランキングとコンテスト</strong> 画面は実験段階です。ルートは <code>#/rankings</code> ですが、メインナビゲーションには意図的に表示せず、起動タブとしても復元しません。サイドバー項目がなくても、ルートやエンジンが削除されたわけではありません。</p><h2 id="configure-an-experimental-ranking" tabindex="-1">実験的ランキングを設定する <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;実験的ランキングを設定する {#configure-an-experimental-ranking}&quot;">​</a></h2><p>画面が利用できる環境では、配信者1人、ルーム1つ、ユーザー単位のグループ化、セッション期間で始めます。<code>tiktok.like</code> / <code>like.count</code> など提供されている指標を1つ、重み <code>1</code> で追加します。結果件数を控えめにして定義を作成します。フォームは移動期間と日次期間にも対応し、期間・イベント数の上限やタイムゾーン差を明示できます。</p><p>ソースを増やす前にスナップショットを読みます。一時停止・再開はランキングの収集に作用し、リセットは意図的にランキング状態を消します。競技の設定と投票関連ソースには独自のグループ化規則があります。ポイントのリセットで競技もリセットされる、またはすべての独自グループが全指標で使えるとは考えないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>通常の順位表は利用でき、専用管理ページは実験段階です。スコアはホストが計算し、表示フィードの行数から算出しません。このガイドは実配信・OBS の動作や競技の全組み合わせを確認するものではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>空のスコアでは配信者、ルーム、ソースの有効状態、期間、一時停止を確認します。非対応のソース・グループの組み合わせは架空のフィールド名で補わず削除します。リセット前に重要データを<a href="./../preferences/backups.html">バックアップ</a> し、報告には定義 ID と診断コードを含めます。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>Points 表は 100 人を取得し、その行だけを検索・並べ替えます。更新や名前順への変更でデータベース全体を検索するわけではありません。フィードのランキングは配信者・ルームのセッションごとに 10 行を表示し、Top はギフトのダイヤ、Likes はいいね数を集計します。追跡上限は 5,000 人です。保存ポイントとは単位と期間を分けて比較してください。</p>',15)])])}const f=a(i,[["render",o]]);export{p as __pageData,f as default};
